import React, { useEffect, useState } from "react";
     const token = localStorage.getItem("token");

function LevelsPage() {
  const [problem, setProblem] = useState([]);
  const [completedLevels, setCompletedLevels] = useState([1]); 
  // Level 1 unlocked by default
xco
  useEffect(() => {
    fetch("http://localhost:5000/problem")
      .then(res => res.json())
      .then(data => setProblem(data));
  }, []);

  // Check if level is unlocked
  const isUnlocked = (level) => {
    if (level === 1) return true;
    return completedLevels.includes(level - 1);
  };

  // When Start button clicked
  const startLevel = (level) => {
    alert(`Level ${level} completed`);
    setCompletedLevels(prev => [...prev, level]);
  };

  return (
    <div style={{
      backgroundColor: "black",
      color: "yellow",
      fontSize: "20px",
      minHeight: "100vh"
    }}>
      <h1>Problem Table</h1>

      <table border="3" cellPadding="10">
        <thead>
          <tr>
            <th>ID</th>
            <th>Level</th>
            <th>Title</th>
            <th>Description</th>
            <th>Action</th>
          </tr>
        </thead>

        <tbody>
          {problem.map((stu) => {
            const unlocked = isUnlocked(stu.level);

            return (
              <tr key={stu.id} style={{ opacity: unlocked ? 1 : 0.4 }}>
                <td>{stu.id}</td>
                <td>Level {stu.level}</td>
                <td>{stu.title}</td>
                <td>{stu.description}</td>
                <td>
                  <button
                    disabled={!unlocked}
                    onClick={() => startLevel(stu.level)}
                  >
                    {unlocked ? "Start" : "Locked 🔒"}
                  </button>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

export default LevelsPage;
